import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const read=p=>{const base=fs.readFileSync(p,'utf8');if(p!=='irrigacao-react/src/main.tsx')return base;const dir='irrigacao-react/src/modules';const modules=fs.existsSync(dir)?fs.readdirSync(dir).filter(x=>/\.(tsx|ts)$/.test(x)).map(x=>fs.readFileSync(dir+'/'+x,'utf8')).join('\n'):'';return base+'\n'+modules};
