test('Revisao Geral 11.0 consolida navegacao cabecalho permissoes e mobile',()=>{const u=read('irrigacao-react/src/main.tsx'),c=read('irrigacao-react/src/styles.css'),users=read('server/api/users.js');for(const x of ["section={s}","FAZENDA 2E • LAVOURA","Gestão da fazenda","id==='home'||id==='menu'"])assert.ok(u.includes(x));assert.ok(users.includes("'dashboard','farm','irrigation'"));for(const x of ['Revisão Geral 11.0','repeat(5,minmax(0,1fr))','font-size:16px!important','.farmTabs105{top:88px}'])assert.ok(c.includes(x))});

test('Guardian 5.2 respeita recuperação posterior de alerta persistido',()=>{const s=read('scripts/quality-agent.mjs');assert.ok(s.includes("x.type==='viveiro_audit_recovered'"));assert.ok(s.includes('active.delete(c)'));});

// guardian-weather-offline-regression
test("Quality Guardian inclui Weather2-2 offline na auditoria persistida do Viveiro",()=>{ const q=fs.readFileSync("scripts/quality-agent.mjs","utf8"); assert.match(q,/bad=new Set\(\[[^\]]*weather_offline/); });

test('menu principal nao vaza estilos fixos para submenus internos',()=>{const u=read('irrigacao-react/src/main.tsx'),c=read('irrigacao-react/src/styles.css');assert.ok(u.includes('className="bottomNav" aria-label="Navegação principal"'));assert.ok(c.includes('nav.bottomNav{'));assert.ok(!/(^|})nav\{/.test(c));assert.ok(c.includes('.coffeeSavedProgram nav{display:flex'));assert.ok(c.includes('.farmTabs105{'))});

test('Viveiro possui helpers de horario e dias usados na renderizacao',()=>{const s=read('irrigacao-react/src/main.tsx');assert.match(s,/function minsClock\(/);assert.match(s,/function clockMins\(/);assert.match(s,/function bitCount\(/);assert.match(s,/value=\{minsClock\(startMin\)\}/);assert.match(s,/String\(bitCount\(days\)\)/)});

test('Auditoria geral: Guardian deduplica event_id antes de classificar falhas repetidas',()=>{
 const s=read('server/continuous/seconds-manager.js');
 assert.match(s,/const uniqueHistory=Array\.from\(new Map\(history\.map/);
 assert.match(s,/const recent30=uniqueHistory\.filter/);
 assert.match(s,/const restarts=uniqueHistory\.filter/);
});
test('Auditoria geral: ESP32 usa o estado ativo viveiro-segundos com fallback legado',()=>{
 const s=read('server/api/esp32-controller.js');
 assert.match(s,/VIVEIRO_FILE=path\.join\(ROOT,'viveiro-segundos\.json'\)/);
 assert.match(s,/VIVEIRO_LEGACY_FILE=path\.join\(ROOT,'viveiro-seconds\.json'\)/);
 assert.match(s,/\[VIVEIRO_FILE,VIVEIRO_LEGACY_FILE\]/);
});

test('Precisão R1: os 30 s físicos começam na confirmação ON do ESP32',()=>{
 const s=read('server/continuous/seconds-manager.js');
 assert.match(s,/expected_off_at:\(relayOnAt\|\|Date\.now\(\)\)\+maxOn\*1000/);
 assert.doesNotMatch(s,/expected_off_at:\(relayOnCommandAt\|\|relayOnAt/);
});


test('Guardian não conta start_delay como uma segunda falha física',()=>{
 const s=read('server/continuous/seconds-manager.js');
 assert.match(s,/\['viveiro_error','viveiro_start_failure'\]\.includes/);
 assert.doesNotMatch(s,/\['viveiro_error','viveiro_start_failure','viveiro_start_delay'\]\.includes/);
 assert.match(s,/Falhas independentes de irrigação se repetiram nos últimos 30 minutos/);
});
